type Theme = "light" | "dark"

export const STORAGE_KEY = "theme"
export const SYSTEM_LIGHT_QUERY = "(prefers-color-scheme: light)"

const readTheme = (): Theme =>
  document.documentElement.dataset.theme === "light" ? "light" : "dark"

const systemTheme = (): Theme =>
  window.matchMedia(SYSTEM_LIGHT_QUERY).matches ? "light" : "dark"

const hasStoredTheme = () => {
  try {
    const stored = localStorage.getItem(STORAGE_KEY)
    return stored === "light" || stored === "dark"
  } catch {
    return false
  }
}

// Each element's colour transition would otherwise run on its own duration, so
// the page would change colour in a staggered sequence.
const withoutTransitions = (apply: () => void) => {
  const style = document.createElement("style")
  style.textContent = "*,*::before,*::after{transition:none!important}"
  document.head.append(style)
  apply()
  // Reading a computed value commits the new colours while transitions are off;
  // without it the removal below would coalesce with the change.
  void getComputedStyle(document.documentElement).color
  requestAnimationFrame(() => style.remove())
}

const applyTheme = (theme: Theme) =>
  withoutTransitions(() => {
    document.documentElement.dataset.theme = theme
  })

// Kept in memory as well as storage, so a visitor's pick still wins over a
// system theme change when storage is blocked.
let followsSystem = false

export const toggleTheme = () => {
  const next: Theme = readTheme() === "light" ? "dark" : "light"
  applyTheme(next)
  followsSystem = false
  try {
    localStorage.setItem(STORAGE_KEY, next)
  } catch {
    // Storage can be blocked (private mode); the theme still applies for this visit.
  }
}

export const followSystemTheme = () => {
  followsSystem = !hasStoredTheme()
  window.matchMedia(SYSTEM_LIGHT_QUERY).addEventListener("change", () => {
    if (followsSystem) applyTheme(systemTheme())
  })
}
